CREATE TABLE IF NOT EXISTS live_state (id INTEGER PRIMARY KEY CHECK (id=1), version INTEGER NOT NULL DEFAULT 0, slot_id TEXT, changed_at TEXT);
INSERT OR IGNORE INTO live_state (id,version) VALUES (1,0);
CREATE TABLE IF NOT EXISTS transitions (id INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL UNIQUE, version INTEGER NOT NULL UNIQUE, slot_id TEXT NOT NULL, changed_at TEXT NOT NULL, operator TEXT NOT NULL DEFAULT '', note TEXT NOT NULL DEFAULT '');
